export const LESSONS: LessonDefinition[] = Ki;

export function getLesson(id: string): LessonDefinition | undefined {
  return LESSONS.find((l) => l.id === id);
}

export function runLesson(lesson: LessonDefinition, input: any): { steps: Step[]; output: any } {
  return xi(lesson, input);
}
